[CmdletBinding()]
param([string]$RepoRoot=(Get-Location).Path)
$ErrorActionPreference='Stop'
$RepoRoot=(Resolve-Path -LiteralPath $RepoRoot).Path
if(!(Test-Path -LiteralPath (Join-Path $RepoRoot 'GuideVault.sln'))){throw 'Run from GuideVault repository root.'}
$patch=@'
[{"path":"Dockerfile","before":"c106fe0d842d2d3e139238e4df4bbcb9670b357b7526ef450328050aa5386eb1","after":"ce16430c28286f6ae94a45ac154a955eb5cfbd831082a20a962bacc9a932a60c","payload":""}]
'@ | ConvertFrom-Json
function HashText([string]$s){$sha=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($s)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}}
$pending=@()
foreach($p in $patch){
 $path=Join-Path $RepoRoot $p.path; $exists=Test-Path -LiteralPath $path; $bom=$false; $nl="`n"
 if($exists){$bytes=[IO.File]::ReadAllBytes($path);$bom=$bytes.Length -ge 3 -and $bytes[0] -eq 239 -and $bytes[1] -eq 187 -and $bytes[2] -eq 191;$raw=[IO.File]::ReadAllText($path);if($raw.Contains("`r`n")){$nl="`r`n"};$hash=HashText ($raw.Replace("`r`n","`n"));if($hash -eq $p.after){continue};if(!$p.before -or $hash -ne $p.before){throw "Source mismatch: $($p.path). No files changed."}}
 elseif($p.before){throw "Missing baseline: $($p.path). No files changed."}
 $target=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($p.payload));if((HashText $target) -ne $p.after){throw "Payload hash mismatch: $($p.path)"}
 $pending+=@{name=$p.path;path=$path;exists=$exists;target=$target.Replace("`n",$nl);encoding=[Text.UTF8Encoding]::new($bom)}
}
if(!$pending.Count){Write-Host 'Scanner v6.0.2 already installed.';return}
$backup=Join-Path $RepoRoot ('.guidevault-patch-backups/magazine-scanner-v602-'+(Get-Date -Format 'yyyyMMdd-HHmmss-fff'))
foreach($p in $pending){if($p.exists){$dest=Join-Path $backup $p.name;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest)|Out-Null;Copy-Item -LiteralPath $p.path -Destination $dest}}
try{foreach($p in $pending){New-Item -ItemType Directory -Force -Path (Split-Path -Parent $p.path)|Out-Null;[IO.File]::WriteAllText($p.path,$p.target,$p.encoding);if([IO.File]::ReadAllText($p.path) -cne $p.target){throw "Write verification failed: $($p.name)"}}}catch{foreach($p in $pending){if($p.exists){Copy-Item -LiteralPath (Join-Path $backup $p.name) -Destination $p.path -Force}else{Remove-Item -LiteralPath $p.path -Force -ErrorAction SilentlyContinue}};throw}
Write-Host "Backup: $backup"
Write-Host 'Scanner v6.0.2 Docker dependency correction installed. Build and deploy.'
